def kmp_search(text, pattern):
    if pattern == "":
        return list(range(len(text) + 1))
    lps = build_lps(pattern)
    matches = []
    text_index = pattern_index = 0
    while text_index < len(text):
        if text[text_index] == pattern[pattern_index]:
            text_index += 1
            pattern_index += 1
            if pattern_index == len(pattern):
                matches.append(text_index - len(pattern))
                pattern_index = lps[pattern_index - 1]
        elif pattern_index > 0:
            pattern_index = lps[pattern_index - 1]
        else:
            text_index += 1
    return matches

print(kmp_search("aaaa", "aa"))  # [0, 1, 2]

def rabin_karp(text, pattern, base=256, modulus=1_000_000_007):
    n, m = len(text), len(pattern)
    if m == 0:
        return list(range(n + 1))
    if m > n:
        return []
    high = pow(base, m - 1, modulus)
    pattern_hash = window_hash = 0
    for index in range(m):
        pattern_hash = (pattern_hash * base + ord(pattern[index])) % modulus
        window_hash = (window_hash * base + ord(text[index])) % modulus
    matches = []
    for start in range(n - m + 1):
        if window_hash == pattern_hash and text[start:start + m] == pattern:
            matches.append(start)
        if start < n - m:
            window_hash = (window_hash - ord(text[start]) * high) % modulus
            window_hash = (window_hash * base + ord(text[start + m])) % modulus
    return matches

print(rabin_karp("banana", "ana"))  # [1, 3]

