class Trie:
    def __init__(self):
        self.root = {"children": {}, "is_word": False}

    def insert(self, word):
        node = self.root
        for character in word:
            node = node["children"].setdefault(
                character, {"children": {}, "is_word": False}
            )
        node["is_word"] = True

    def _walk(self, text):
        node = self.root
        for character in text:
            if character not in node["children"]:
                return None
            node = node["children"][character]
        return node

    def search(self, word):
        node = self._walk(word)
        return node is not None and node["is_word"]

    def starts_with(self, prefix):
        return self._walk(prefix) is not None

trie = Trie()
trie.insert("apple")
print(trie.search("app"), trie.starts_with("app"))  # False True

def is_palindrome(text):
    left, right = 0, len(text) - 1
    while left < right:
        if text[left] != text[right]:
            return False
        left += 1
        right -= 1
    return True

print(is_palindrome("level"))  # True

def longest_palindrome_center(text):
    best_start, best_length = 0, 0
    def expand(left, right):
        while left >= 0 and right < len(text) and text[left] == text[right]:
            left -= 1
            right += 1
        return left + 1, right - left - 1

    for center in range(len(text)):
        for left, right in ((center, center), (center, center + 1)):
            start, length = expand(left, right)
            if length > best_length:
                best_start, best_length = start, length
    return text[best_start:best_start + best_length]

print(longest_palindrome_center("babad"))  # bab 或 aba

def longest_palindrome_dp(text):
    size = len(text)
    if size == 0:
        return ""
    dp = [[False] * size for _ in range(size)]
    best_start, best_length = 0, 1
    for right in range(size):
        for left in range(right + 1):
            if text[left] == text[right] and (right - left <= 2 or dp[left + 1][right - 1]):
                dp[left][right] = True
                length = right - left + 1
                if length > best_length:
                    best_start, best_length = left, length
    return text[best_start:best_start + best_length]

print(longest_palindrome_dp("cbbd"))  # bb
